def test():
    ast.parse(SOURCE)
    assert "def research_route(" in SOURCE and "def staged_route(" not in SOURCE
    assert "r=research_route(token)" in SOURCE
    with tempfile.TemporaryDirectory() as d:
        x=Path(d)/'v17b.py';x.write_text(SOURCE,encoding='utf-8')
        rc=subprocess.call([sys.executable,str(x),'--test'])
        if rc:raise RuntimeError('V17B_TEST_FAILED')
    print('[PASS] V17B source and complete deterministic tests; scanner unchanged')

def install():
    test()
    TARGET.parent.mkdir(parents=True,exist_ok=True)
    old=TARGET.read_bytes() if TARGET.is_file() else b''
    if old==SOURCE.encode('utf-8'):
        print('[PASS] V17B_ALREADY_INSTALLED');return
    if TARGET.is_symlink():raise RuntimeError('TARGET_SYMLINK_REFUSED')
    BACK.mkdir(parents=True,exist_ok=True)
    if old:
        name=BACK/('v17_pre_v17b_'+hashlib.sha256(old).hexdigest()[:16]+'.bak')
        if not name.exists():
            name.write_bytes(old)
            print('[BACKUP]',name)
    with tempfile.NamedTemporaryFile('wb',suffix='.tmp',dir=TARGET.parent,delete=False) as f:
        f.write(SOURCE.encode('utf-8'));tmp=Path(f.name)
    try:os.replace(tmp,TARGET)
    finally:tmp.unlink(missing_ok=True)
    assert TARGET.read_bytes()==SOURCE.encode('utf-8')
    print('[PASS] V17B_COMPLETE_READ_ONLY_AUDITOR_REPLACEMENT')
    print('[SHA256]',hashlib.sha256(TARGET.read_bytes()).hexdigest())
    print('[BOUNDARY] scanner V16 and ORACLE402 unchanged; no signing; no broadcast')

def main():
    a=argparse.ArgumentParser();g=a.add_mutually_exclusive_group(required=True)
    g.add_argument('--test',action='store_true');g.add_argument('--install',action='store_true')
    x=a.parse_args()
    try:test() if x.test else install();return 0
    except Exception as exc:
        print('[V17B_HOLD]',type(exc).__name__+':'+str(exc)[:180]);return 2
if __name__=='__main__':raise SystemExit(main())
